pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division against capacity fractions (dead-space classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries: leftover <= 10 is "dead space" (only items >=10 fit nothing well).
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 35.0; // unusable dead space -> great placement
    } else if post_residual <= 20 {
        score -= 12.0; // still hard to reuse
    } else if post_residual <= 30 {
        score -= 4.0;
    } else if post_residual <= 50 {
        score += 6.0; // mid leftovers are reusable, mildly neutral
    } else {
        score += 10.0; // large leftover: item was small, placement wasteful
    }

    // Modulo-style harmonic coupling: leftover that is itself a "harmonic"
    // fraction of capacity (25, 33, 50, 66, 75) is highly reusable.
    let harmonics = [25u32, 33, 34, 50, 66, 67, 75];
    for h in harmonics.iter() {
        let d = (post_residual as i64 - *h as i64).abs();
        if d <= 2 {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let fill_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 15.0 * fill_ratio;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open new bins when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // opening early in the stream or with many open bins is cheaper to avoid
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating: prefer bins with small residual
    // relative to the mean (fills fuller bins first).
    score += 0.15 * (mean_residual - pr).max(-50.0).min(50.0);

    // Slight preference for fewer open bins when residuals are similar.
    score += 0.02 * open_bins_count as f64;

    score
}

