pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward closing a bin completely.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if the leftover space exactly matches (or can hold) the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 250.0; // chain fit: next item closes this bin too
        } else if post_residual >= next_item_size {
            // leftover usable by next item: reward proportionally to how snug the chain is
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 120.0 * snug;
        } else {
            // dead space the next item cannot use: penalize small unusable slivers hardest
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 80.0; // tiny unusable fragment
            } else {
                score += 30.0 * (dead / bin_capacity as f64);
            }
        }
    }

    // Compare against mean residual: bins tighter than average are more valuable to fill.
    let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless residual space
    // is genuinely scarce across open bins.
    if bin_residual == bin_capacity {
        let avg_tight = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // If open bins are quite full on average, a new bin is reasonable; otherwise discourage.
        score += 60.0 + 100.0 * (1.0 - avg_tight) * (1.0 - 0.3 * progress);
    }

    // Mild preference for using fewer bins overall.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual relative to capacity).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 45.0 * (1.0 - tightness).powi(6);

    // Exact-fill bonus: perfectly closed bins are ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: mild penalty unless bin closes.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bins should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins lose against decent fits.
        score += 30.0;
        // But if many open bins exist and mean residual is large, opening fresh
        // bins can be beneficial for future flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - progress);
        // If nothing else fits well (large item, small mean residual), new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 35.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate waste into few bins).
    let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * diff;

    // Mild preference for fewer open bins early in the stream (keep packing tight),
    // relaxes later as streams are long.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer low post-residual, smoothly modulated by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear coupling: penalize mid-range residual dead space quadratically.
    score += 8.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly as stream advances.
    score -= 12.0 * (1.0 - pr_norm).powi(3) * (0.5 + progress);

    // Last-chance bonus: this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64;
            score -= 4.0 * (1.0 - slack / cap) * (1.0 - progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer bins near the mean to balance load.
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: make empty bins moderately attractive only when
    // the item fits poorly elsewhere (large post-residual in existing bins).
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress);
        if next_item_size > 0 && (bin_capacity as u32) >= next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into 10-wide bands.
    // Residuals in [1..9] are near-perfect fits -> strong reward.
    let post = post_residual as i64;
    let band = if post == 0 { 0 } else { ((post + 9) / 10) as i64 };

    match band {
        0 => score -= 60.0,                 // perfect fit
        1 => score -= 45.0,                 // residual <= 9: unusable dead space, great
        2 => score -= 25.0,                 // residual <= 19: only tiny items fit
        3 => score -= 10.0,
        4 => score += 5.0,
        5 => score += 12.0,
        6 => score += 20.0,
        _ => score += 25.0,                 // residual >= 70: half-empty bin
    }

    // Modulo-10 harmonic classes: residual classes divisible by 10 pair well
    // with typical item granularities.
    let m = post % 10;
    if post > 0 {
        score += match m {
            0 => -8.0,   // clean class, maximally reusable
            5 => -4.0,   // half-class decent
            1 | 2 | 3 | 4 => 0.0,
            _ => 4.0,    // 6..9 slightly awkward
        };
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n == post {
            score -= 40.0;
        } else if n <= post {
            // reward proportional to how well next item fills the leftover
            let fill = n as f64 / post as f64;
            score -= 10.0 * fill;
            // harmonic class of post - next
            let rem = post - n;
            if rem <= 9 && rem >= 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot use this residual: penalize leaving medium gaps
            if post >= 10 && post <= 49 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible.
    if bin_residual == bin_capacity {
        // base new-bin cost; becomes attractive if best open fit leaves large waste
        score += 30.0;
        // scale with stream progress: later on, consolidate more
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - t);
        if post == 0 {
            // exact fit into fresh bin (item == capacity) - fine
            score -= 60.0;
        }
    }

    // Prefer filling bins that are already below mean residual (more full).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: gaps that are too small to be useful
    // for typical future items are heavily penalized. With item sizes
    // possibly as small as 1, penalize "thin" gaps non-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Dead-space term grows sharply as the gap shrinks below ~15.
        let dead = (15.0 - pr).max(0.0);
        score += dead * dead * 0.35;
        // Any nonzero residual below 10 is essentially wasted space.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this bin; if the next item would be stranded, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.2;
        } else {
            score -= (post_residual - next_item_size).min(20) as f64 * 0.3;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spawning extra bins when many are open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 4.0;
        // But allow a fresh bin if current open bins are nearly full on average.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 2.0;
        // Prefer bins whose residual is tight relative to the mean.
        score += ((bin_residual as f64) - mean_residual) * 0.15;
    }

    // Early in the stream, be slightly more willing to open bins (better
    // long-run structure); late in the stream, squeeze existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * -6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain fit: big reward; degrade quadratically with gap.
            score -= 60.0 - gap * 0.9 + gap * gap * 0.01;
        } else {
            // Next item cannot follow: penalize proportionally to overflow amount.
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 + over * 0.5;
        }
    } else {
        // Last item: prefer tightest fill.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // space; using them is good, leaving them is wasteful.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= 0.6 * (mean_residual - resid_f);
    } else {
        score += 0.3 * (resid_f - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post_residual would be tiny/dead).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        if post_residual < 10 {
            score += 15.0; // dead-space guard
        }
    }

    // New-bin candidate: neutral-ish base, only attractive when no open bin
    // offers a decent fit. Penalize mildly so tight existing fits win.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large relative to capacity, opening fresh is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // Dead-space penalty: small post residuals (<10, unusable for items >=10)
    // are perfect if zero, wasteful otherwise.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Early stream: be slightly more willing to open bins / spread load.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    // Many open bins: prefer consolidation, penalize scattering.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: residual too small for the smallest plausible future item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 {
        // Fraction of residual unusable relative to item granularity.
        score += 0.15 * (post_residual % 10) as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use leftover: mild penalty proportional to waste
            score += 0.05 * post_residual as f64;
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, favor compacting into few bins; later, more relaxed.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.2 * progress;

    // Global state: many open bins with high mean residual -> favor reusing bins.
    if open_bins_count > 2 {
        let reuse_bonus = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 5.0 * reuse_bonus;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no open bin fits, opening is fine (fitting_bins_count reflects open bins only).
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in stream with large next item, a fresh bin may be strategic.
        if next_item_size >= 60 && progress > 0.5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    let tightness = 1.0 - pr_norm * pr_norm;
    score -= 30.0 * tightness * (0.5 + progress);
    score += 12.0 * pr_norm * pr_norm * (1.0 - prog_cu);

    // Reward near-perfect fills more strongly later in the stream
    let perfect = (pr_norm * (1.0 - pr_norm)).max(0.0); // peaks at pr_norm = 0.5
    score -= 8.0 * perfect * (1.0 + 2.0 * prog_sq);

    // Penalize dead space relative to mean residual smoothly
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // Lookahead: reward leaving space close to next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (pr_norm - nxt).abs();
        score -= 10.0 * (1.0 - gap * gap) * (0.4 + 0.6 * progress);
    }

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prog_cu);
    }

    // Mild preference for consolidating into fewer bins early
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Slight reward for larger items going into tighter bins
    score -= 5.0 * item_norm * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by large
    // "harmonic" denominators (10, 20, 25, 50) are more reusable, since
    // typical item sizes are multiples of small integers.
    let harmonic_bonus = if post_residual == 0 {
        60.0 // perfect closure: strongly reward
    } else if post_residual % 50 == 0 {
        40.0
    } else if post_residual % 25 == 0 {
        30.0
    } else if post_residual % 20 == 0 {
        25.0
    } else if post_residual % 10 == 0 {
        20.0
    } else if post_residual % 5 == 0 {
        12.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize small dead space that nothing can use (post_residual < 10
    // cannot fit any item => unusable waste), unless it is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportionally to how well the next item fills the gap
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 25.0 * fill;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // the item is huge and no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // penalize new bin more as the fit in existing bins would be decent
        score += 55.0 * (1.0 - poor_fit);
        // slightly cheaper to open bins early in the stream
        score -= 5.0 * (1.0 - progress);
    }

    // Mild pressure against bin proliferation
    score += open_bins_count as f64 * 0.3;

    // Prefer filling bins below mean residual (i.e., tighter bins)
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item (>=1) can use
    // are pure waste; gaps below the minimum item size are the worst.
    if post_residual == 0 {
        score -= 100.0; // perfect fit: ideal, no dead space at all
    } else if post_residual < 10 {
        score += 60.0; // unusable tiny gap -> heavy penalty
    } else if post_residual <= 20 {
        score += 25.0; // hard-to-fill small gap
    } else if post_residual <= 40 {
        score += 8.0; // moderate gap
    }

    // Reward tight fits relative to bin capacity (waste fraction penalty).
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Open-bin pressure: discourage spreading across many bins when
    // residual space is still usable; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 2.0;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only when the mean residual is small (bins are nearly full).
    if mean_residual < 30.0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; if the next item cannot use the gap,
    // penalize creating a gap that blocks the known next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // New-bin candidate: opening a fresh bin is only attractive when no
    // open bin offers a decent fit (post_residual would be large waste
    // elsewhere). Make fresh bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if the item is huge relative to capacity, a fresh bin is fine
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it as a fallback with a moderate default score.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when the current bin would leave
        // unusable dead space or this is a last-chance situation.
        let dead = (post_residual as i64) - (next_item_size as i64);
        if next_item_size > 0 && dead < 0 && post_residual > 0 {
            // Current bin leaves dead space smaller than next item -> prefer new bin.
            score -= 60.0;
        } else {
            // Neutral fallback, slightly above good chain fits.
            score += 25.0;
        }
        return score;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64) - (next_item_size as i64);
        if diff == 0 {
            // Perfect chain: item + next item fill this bin completely.
            score -= 100.0;
        } else if diff > 0 {
            // Next item fits with slack left; penalize leftover slack proportionally.
            score -= 50.0 - (diff as f64).min(50.0);
        } else {
            // Next item does NOT fit here: dead space penalty grows with tightness.
            let dead = (-diff) as f64;
            score += dead * 0.8;
            // Small dead space (< 10) is nearly unusable given min item size ~1..100
            if dead < 10.0 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer tightest fit (smallest post residual), already the base.
        score -= 20.0;
    }

    // Relative to mean residual: bins with residual far below mean are "tight"
    // and should be filled aggressively; bins above mean have room to spare.
    let rel = (bin_residual as f64) - mean_residual;
    score -= rel * 0.15;

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Slight preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large leftover space lightly, but reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.5 + 5.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space for the known next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item
    // fits poorly everywhere else or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If mean residual is low (bins are full), a new bin is fine; otherwise discourage.
        score += 15.0 * (1.0 - pressure);
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Tightness coupling: prefer bins whose residual is close to item size (best-fit flavor).
    score += (bin_residual - item_size) as f64 * 0.1;

    // Time horizon: early in the stream, be frugal with bins; late, tolerate slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Crowding: with many open bins, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins below-average residual (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (1.0 + 60.0 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) * (0.5 + 1.5 * progress);
        } else {
            score -= (pr - nxt) * 0.2 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many are open with room
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - progress);
        // New bin attractive if mean residual is small
        score -= 15.0 * (mean_residual / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left after placement

    // Penalize residuals in "dead zone" classes: too small for typical items
    // Items >= 10 in original spec, 1..100 generally; treat residual < 12 as near-dead.
    if post_residual < 12 {
        score -= 40.0; // perfect fill, reward heavily
    } else {
        // modulo classes on post_residual: residuals congruent to small remainders
        // relative to common item sizes (multiples of 5/10) are more reusable.
        let m10 = post_residual % 10;
        let m5 = post_residual % 5;
        // residuals that are multiples of 10 are "harmonic" with item sizes
        score -= match m10 {
            0 => 18.0,
            _ => match m5 {
                0 => 9.0,
                _ => 0.0,
            },
        } as f64;

        // dead-space penalty grows as residual falls below smallest plausible item
        if frac < 0.15 {
            score += 25.0 * (0.15 - frac);
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // harmonic class: next item leaves a multiple-of-10 remainder
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 {
                score -= 22.0;
            } else if rem < 10 {
                score += 8.0; // creates tiny dead space
            }
        } else {
            // next item won't fit here; slight penalty if this bin is the only option
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild default penalty so that
    // decent fits into open bins win, but very poor fits (large leftover) lose.
    if bin_residual == bin_capacity {
        score += 45.0;
        // opening early when stream is young is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins tighter than average (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Small tie-breaker toward lower post_residual via integer division class
    let div_class = post_residual / 10;
    score += div_class as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items (<= 10) are essentially unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate dead space (10..=20) is risky but partially usable.
    else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (near-perfect packing) strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Reward bins that can also host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating a gap that cannot host the next item.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // more bins; prefer filling existing ones.
    let open_pressure = (open_bins_count as f64) / 10.0;
    score += open_pressure * (post_residual as f64);

    // New-bin candidate: only attractive when the item fits poorly anywhere
    // else (large dead space would result) or when few bins are open.
    if bin_residual == bin_capacity {
        let worst_case_dead = (bin_residual - item_size) as f64;
        score = 40.0 + worst_case_dead - (open_bins_count as f64) * 2.0;
        // If the next item would fit in the fresh bin too, slight bonus.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: low post_residual is already rewarded by base term.
    // Aggressive 2-step lookahead: if the NEXT item can exactly fill post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the remaining space; penalize dead space proportionally.
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.3 * unusable.min(post_residual as f64);
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better candidates.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when item is huge relative
    // to capacity or all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Slight stream-progression bias: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> be conservative; late stream -> fill aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let horizon = 1.0 - progress;

    // Reward tight fits: small post_residual is already the base score.
    // Extra reward for near-perfect fits (post_residual < 10).
    if post_residual < 10 {
        score -= 12.0 * horizon;
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly favor this bin (chain fill).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 == nr {
            score -= 20.0;
        } else if (post_residual as f64) >= nr {
            score -= 6.0 * (1.0 - (post_residual as f64 - nr) / bin_capacity as f64);
        } else {
            // Next item cannot fit here; dead space penalty scaled by wasted gap.
            score += 0.15 * (nr - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * horizon;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize it
    // unless the item is large relative to capacity (poor fit elsewhere likely)
    // or many bins are open and mean residual is small (fragmented state).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0);
        let mut penalty = 25.0; // base cost of a new bin
        // If item is large and existing mean residual can't help, new bin is fine.
        penalty -= 20.0 * large_item;
        // If open bins are fragmented (low mean residual), new bin is more attractive.
        penalty -= 10.0 * (1.0 - fragmentation);
        // Late in the stream, prefer closing out bins rather than opening.
        penalty += 8.0 * progress;
        score += penalty.max(-5.0);
    }

    // Prefer bins whose residual is below the mean (tighter-than-average bins
    // should be consumed first), leaving looser bins for future items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Mild diversity pressure: with many open bins, slightly favor filling
    // existing bins over spreading.
    score += 0.02 * open_bins_count as f64 * horizon;

    // Small absolute-difference shaping: reward residual close to half capacity
    // being consumed (keeps future flexibility).
    let flex = ((post_residual as f64) - (bin_capacity as f64) / 2.0).abs();
    score += 0.03 * flex * horizon;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth progress coupling: later in the stream, tight fits matter more.
    score *= 1.0 + 0.6 * progress * (1.0 - norm_pr);

    // Lookahead: reward residual that can host the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        let fit_kernel = 1.0 / (1.0 + (diff / 20.0) * (diff / 20.0));
        score -= 12.0 * fit_kernel * (1.0 - progress);
        // Penalize residuals that are just barely too small for the next item.
        if diff < 0.0 {
            score += 6.0 * (-diff / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidating many open bins.
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Slight penalty for near-empty usage of an existing bin vs opening new.
    if norm_pr > 0.9 {
        score += 5.0 * (norm_pr - 0.9);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of small
    // moduli is more likely reusable by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit, best outcome
    } else {
        // modularity reward: residual divisible by common item granularities
        let mut mod_bonus = 0.0;
        if pr % 10 == 0 { mod_bonus += 4.0; }
        if pr % 5 == 0 { mod_bonus += 2.0; }
        if pr % 20 == 0 { mod_bonus += 2.0; }
        if pr % 25 == 0 { mod_bonus += 1.5; }
        score -= mod_bonus;

        // penalize tiny unusable dead space (< 10 means nothing can ever fit)
        if pr < 10 {
            score += 15.0;
        }
    }

    // Integer-division thresholds on next_item_size vs post_residual:
    // if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual; scale by how tight
            let nxt_post = pr - next_item_size;
            if nxt_post < 10 { score -= 8.0; } else { score += nxt_post as f64 * 0.3; }
        } else {
            // next item won't fit here; slight penalty if we'd be stranded
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        // neutral-ish baseline; add small penalty so a decent fit in an open
        // bin wins, but subtract if the item is large (fresh bin useful)
        score += 6.0;
        if item_size > bin_capacity / 2 {
            score -= 4.0;
        }
    }

    // Late in the stream, consolidate: prefer bins below mean residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.1 * progress;

    // Mild preference for tighter existing bins overall
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
