    let rf = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: tight-fit preference with sharper non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * rf) + 14.0 * rf.powi(3);

    // Progress coupling: tighten as the stream advances.
    score *= 1.0 - 0.35 * progress * rf;
    score -= 6.0 * progress * (1.0 - rf).powi(2);

    // Residual diversity pressure, relaxed late when consolidation matters more.
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * (1.0 - dev).powi(2) * (1.0 - 0.4 * progress);

    // Lookahead: reward leaving space for next item; stronger when next item is large.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // Slack left for next item: prefer slack close to nxt (perfect chaining).
            let slack = (pr - nxt) / cap;
            score -= 5.0 * (1.0 - slack.abs()) + 2.0 * (nxt / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin decision: open a fresh bin only when it enables a good chain with
    // the next item AND few alternatives exist, or when the stream is early and
    // open bins are all poor fits (high post_residual elsewhere).
    if is_new_bin {
        let nxt = next_item_size as f64;
        let chain_quality = if nxt > 0.0 { 1.0 - ((cap - nxt) / cap) } else { 0.5 };
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln().max(0.0) };
        let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64).sqrt();
        score += 3.0 + 0.5 * fitting_bins_count as f64
            - 6.0 * chain_quality * (1.0 - progress)
            - 2.5 * scarcity
            + 1.5 * open_pressure;
        // Late stream: opening new bins is almost always bad unless nothing fits.
        if progress > 0.7 && fitting_bins_count > 0 {
            score += 4.0 * progress;
        }
    } else {
        // Reward near-perfect fills strongly (compaction driver).
        if rf < 0.05 {
            score -= 3.0 * (1.0 - rf / 0.05);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
