    score -= harmonic_bonus;

    // Unusable dead space penalty (nothing fits below 10).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Progress coupling: tighten choices as the stream advances.
    score *= 1.0 - 0.35 * progress * (pr / cap);
    score -= 6.0 * progress * (1.0 - pr / cap).powi(2);

    // Lookahead: reward residuals that can host the next item, scaled by fit quality.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual {
            let fill = nxt / pr;
            score -= 10.0 + 25.0 * fill;
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Residual diversity: discourage clustering near the mean residual.
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * (1.0 - dev).powi(2);

    // Last-chance bin: strongly avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening fresh bins, scaled by how many
    // open bins already fit the item and how poor the fresh-bin fit is.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = (bin_residual - item_size) as f64 / cap;
        score += 55.0 * (1.0 - poor_fit) + 3.0 + 0.5 * fitting_bins_count as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Mild pressure against bin proliferation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let item = item_size as f64;

    // Base: tight-fit preference with stronger non-linear sharpening.
    let mut score = pr * (1.0 + 0.9 * pr / cap) + 16.0 * (pr / cap).powi(3);

    // Perfect-fit snap: near-zero waste gets an aggressive reward.
    if pr <= 2.0 {
        score -= 14.0 - 2.0 * pr;
    }

    // Stream-progress coupling: early tolerance, late tightening.
    score *= 1.0 - 0.4 * progress * (pr / cap);
    score -= 7.0 * progress * (1.0 - pr / cap).powi(2);

    // Residual diversity: penalize near-mean residuals.
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.5 * (1.0 - dev).powi(2);

    // Lookahead: reward leaving room for the next item, graded by slack quality.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            // Reward good next-fit slack, but punish leaving a uselessly tiny gap.
            score -= 6.0 * (1.0 - slack);
            if slack > 0.0 && slack < 0.05 {
                score += 4.0; // awkward sliver of leftover space
            }
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Two-item lookahead: does the next item still fit after this one?
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let after_next = pr - next_item_size as f64;
        if after_next >= 1.0 {
            score -= 2.0 * (after_next / cap);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin decision: penalize opening a bin, but relax the penalty when the
    // item is large relative to capacity late in the stream (avoid fragmenting
    // many partially-filled bins with big items).
    if bin_residual == bin_capacity {
        let big_item = item / cap;
        let mut new_bin_penalty = 3.5 + 0.6 * fitting_bins_count as f64;
        if big_item > 0.6 && progress > 0.5 {
            new_bin_penalty *= 0.4;
        }
        // If next item is huge and no open bin could host it anyway, a fresh
        // bin is relatively more attractive.
        if next_item_size as f64 > 0.8 * cap {
            new_bin_penalty -= 2.0;
        }
        score += new_bin_penalty;
    }

    score
}
